  rating = 'all'; query = ''; neighborhood = ''; photosOnly = false;
  el<HTMLInputElement>('#search').value = '';el<HTMLSelectElement>('#neighborhood').value = '';el<HTMLInputElement>('#photos-only').checked = false;
