+  if (payload.status !== 'OK' || !payload.results?.length) throw new Error(payload.error_message || 'Google could not calculate elevation for this stairway.');
+  const elevations = payload.results.map(result => result.elevation);
+  const gainMeters = elevations.slice(1).reduce((total, elevation, index) => total + Math.max(0, elevation - elevations[index]), 0);
